38	// addDependency adds a dependency on the given resource to the set of deps.
39	//
40	// The behavior of this method depends on whether or not the resource is a custom resource, a local component resource,
41	// a remote component resource, a dependency resource, or a rehydrated component resource:
42	//
43	//   - Custom resources are added directly to the set, as they are "real" nodes in the dependency graph.
44	//   - Local component resources act as aggregations of their descendents. Rather than adding the component resource
45	//     itself, each child resource is added as a dependency.
46	//   - Remote component resources are added directly to the set, as they naturally act as aggregations of their children
47	//     with respect to dependencies: the construction of a remote component always waits on the construction of its
48	//     children.
49	//   - Dependency resources are added directly to the set.
50	//   - Rehydrated component resources are added directly to the set.
51	//
52	// In other words, if we had:
53	//
54	//			  Comp1
55	//		  /     |     \
56	//	  Cust1   Comp2  Remote1
57	//			  /   \       \
58	//		  Cust2   Cust3  Comp3
59	//		  /                 \
60	//	  Cust4                Cust5
61	//
62	// Then the transitively reachable resources of Comp1 will be [Cust1, Cust2, Cust3, Remote1].
63	// It will *not* include:
64	// * Cust4 because it is a child of a custom resource
65	// * Comp2 because it is a non-remote component resoruce
66	// * Comp3 and Cust5 because Comp3 is a child of a remote component resource
67	func addDependency(ctx context.Context, deps map[URN]Resource, res, from Resource) error {
68		if _, custom := res.(CustomResource); !custom {
69			// If `res` is the same as `from`, exit early to avoid depending on
70			// children that haven't been registered yet.
71			if res == from {
72				return nil
73			}
74	
75			for _, child := range res.getChildren() {
76				if err := addDependency(ctx, deps, child, from); err != nil {
77					return err
78				}
79			}
80			// keepDependency() returns true for remote component resources, dependency resources,
81			// and rehydrated component resources.
82			if !res.keepDependency() {
83				return nil
84			}
85		}
86	
87		urn, _, _, err := res.URN().awaitURN(ctx)
88		if err != nil {
89			return err
90		}
91		deps[urn] = res
92		return nil
93	}
