95	// expandDependencies expands the given slice of Resources into a set of URNs.
96	func expandDependencies(ctx context.Context, deps []Resource) (map[URN]Resource, error) {
97		set := map[URN]Resource{}
98		for _, r := range deps {
99			if err := addDependency(ctx, set, r, nil /* from */); err != nil {
100				return nil, err
101			}
102		}
103		return set, nil
104	}
