123	// marshalInputs turns resource property inputs into a map suitable for marshaling.
124	func marshalInputsOptions(props Input, opts *marshalOptions) (resource.PropertyMap, map[string][]URN, []URN, error) {
125		deps := map[URN]struct{}{}
126		pmap, pdeps := resource.PropertyMap{}, map[string][]URN{}
127	
128		if props == nil {
129			return pmap, pdeps, nil, nil
130		}
131	
132		marshalProperty := func(pname string, pv any, pt reflect.Type) error {
133			// Get the underlying value, possibly waiting for an output to arrive.
134			v, resourceDeps, err := marshalInputOptions(pv, pt, opts)
135			if err != nil {
136				return fmt.Errorf("awaiting input property %q: %w", pname, err)
137			}
138	
139			// Record all dependencies accumulated from reading this property.
140			allDeps, err := expandDependencies(context.TODO(), resourceDeps)
141			if err != nil {
142				return err
143			}
144			for k := range allDeps {
145				deps[k] = struct{}{}
146			}
147	
148			if !v.IsNull() || len(allDeps) > 0 {
149				urns := slice.Prealloc[URN](len(allDeps))
150				for v := range allDeps {
151					urns = append(urns, v)
152				}
153				pmap[resource.PropertyKey(pname)] = v
154				pdeps[pname] = urns
155			}
156			return nil
157		}
158	
159		pv := reflect.ValueOf(props)
160		if pv.Kind() == reflect.Ptr {
161			if pv.IsNil() {
162				return pmap, pdeps, nil, nil
163			}
164			pv = pv.Elem()
165		}
166		pt := pv.Type()
167	
168		rt := props.ElementType()
169		if rt.Kind() == reflect.Ptr {
170			rt = rt.Elem()
171		}
172	
173		//nolint:exhaustive // We only need to handle the types we care about.
174		switch pt.Kind() {
175		case reflect.Struct:
176			contract.Assertf(rt.Kind() == reflect.Struct, "expected struct, got %v (%v)", rt, rt.Kind())
177			// We use the resolved type to decide how to convert inputs to outputs.
178			rt := props.ElementType()
179			if rt.Kind() == reflect.Ptr {
180				rt = rt.Elem()
181			}
182			getMappedField := internal.MapStructTypes(pt, rt)
183			// Now, marshal each field in the input.
184			numFields := pt.NumField()
185			for i := 0; i < numFields; i++ {
186				destField, _ := getMappedField(reflect.Value{}, i)
187				tag := destField.Tag.Get("pulumi")
188				tag = strings.Split(tag, ",")[0] // tagName,flag => tagName
189				if tag == "" {
190					continue
191				}
192				err := marshalProperty(tag, pv.Field(i).Interface(), destField.Type)
193				if err != nil {
194					return nil, nil, nil, err
195				}
196			}
197		case reflect.Map:
198			ktype := rt.Key()
199			contract.Assertf(ktype.Kind() == reflect.String,
200				"expected map with string keys, got %v (%v)", ktype, ktype.Kind())
201			for _, key := range pv.MapKeys() {
202				keyname := key.Interface().(string)
203				val := pv.MapIndex(key).Interface()
204				err := marshalProperty(keyname, val, rt.Elem())
205				if err != nil {
206					return nil, nil, nil, err
207				}
208			}
209		default:
210			return nil, nil, nil, fmt.Errorf("cannot marshal Input that is not a struct or map, saw type %s", pt.String())
211		}
212	
213		urns := slice.Prealloc[URN](len(deps))
214		for v := range deps {
215			urns = append(urns, v)
216		}
217		return pmap, pdeps, urns, nil
218	}
