148	func (p *PrimitiveProvider) Check(
149		_ context.Context, req plugin.CheckRequest,
150	) (plugin.CheckResponse, error) {
151		// URN should be of the form "primitive:index:Resource"
152		if req.URN.Type() != "primitive:index:Resource" {
153			return plugin.CheckResponse{
154				Failures: makeCheckFailure("", fmt.Sprintf("invalid URN type: %s", req.URN.Type())),
155			}, nil
156		}
157	
158		unsecret := func(v resource.PropertyValue) resource.PropertyValue {
159			for {
160				if v.IsSecret() {
161					v = v.SecretValue().Element
162					continue
163				}
164				if v.IsOutput() {
165					v = v.OutputValue().Element
166					continue
167				}
168				break
169			}
170			return v
171		}
172	
173		assertField := func(key resource.PropertyKey, typ string,
174			assertType func(resource.PropertyValue) bool,
175		) *plugin.CheckResponse {
176			v, ok := req.News[key]
177			if !ok {
178				return &plugin.CheckResponse{
179					Failures: makeCheckFailure(key, "missing value"),
180				}
181			}
182			v = unsecret(v)
183			if v.IsComputed() {
184				// We can't type check if the value is computed.
185				return nil
186			}
187			if !assertType(v) {
188				return &plugin.CheckResponse{
189					Failures: makeCheckFailure(key, "value is not a "+typ),
190				}
191			}
192	
193			return nil
194		}
195	
196		// Expect all required properties
197		check := assertField("boolean", "boolean", resource.PropertyValue.IsBool)
198		if check != nil {
199			return *check, nil
200		}
201		check = assertField("integer", "number", resource.PropertyValue.IsNumber)
202		if check != nil {
203			return *check, nil
204		}
205		check = assertField("float", "number", resource.PropertyValue.IsNumber)
206		if check != nil {
207			return *check, nil
208		}
209		check = assertField("string", "string", resource.PropertyValue.IsString)
210		if check != nil {
211			return *check, nil
212		}
213		check = assertField("numberArray", "array", resource.PropertyValue.IsArray)
214		if check != nil {
215			return *check, nil
216		}
217		// Check the array is numbers
218		numberArray := unsecret(req.News["numberArray"])
219		for _, v := range numberArray.ArrayValue() {
220			v = unsecret(v)
221			if v.IsComputed() {
222				// We can't type check if the value is computed.
223				continue
224			}
225			if !v.IsNumber() {
226				return plugin.CheckResponse{
227					Failures: makeCheckFailure("numberArray", "array element is not a number"),
228				}, nil
229			}
230		}
231		check = assertField("booleanMap", "map", resource.PropertyValue.IsObject)
232		if check != nil {
233			return *check, nil
234		}
235		// Check the map values are booleans
236		booleanMap := unsecret(req.News["booleanMap"])
237		for _, v := range booleanMap.ObjectValue() {
238			v = unsecret(v)
239			if v.IsComputed() {
240				// We can't type check if the value is computed.
241				continue
242			}
243			if !v.IsBool() {
244				return plugin.CheckResponse{
245					Failures: makeCheckFailure("booleanMap", "map value is not a boolean"),
246				}, nil
247			}
248		}
249	
250		if len(req.News) != 6 {
251			return plugin.CheckResponse{
252				Failures: makeCheckFailure("", fmt.Sprintf("too many properties: %v", req.News)),
253			}, nil
254		}
255	
256		return plugin.CheckResponse{Properties: req.News}, nil
257	}
